  check_window_copy(10, 11, 9, 9, -4, -5);
  check_window_copy(0, 0, 0xFFFF, 0xFFFF, 2, 2);
}

void test_copy_area_from_the_window_marks_the_rows_it_wrote(void) {
  number_canvas();
  canvas_clear_dirty(&cv);
  GC gc = new_gc(0xFFFF, 0);
